package in.terratech.vegmap;
import java.util.*;import java.util.concurrent.CopyOnWriteArrayList;import java.util.concurrent.atomic.AtomicLong;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/listings") public class ListingController {
 final List<Listing> items=new CopyOnWriteArrayList<>();final AtomicLong ids=new AtomicLong(100);final SecurityController sec;
 ListingController(SecurityController s){sec=s;items.add(new Listing(ids.incrementAndGet(),"Tomato",32,18,"kg","Ravi Farm","Moodbidri","demo"));items.add(new Listing(ids.incrementAndGet(),"Onion",28,40,"kg","Lakshmi Greens","Kinnigoli","demo"));items.add(new Listing(ids.incrementAndGet(),"Beans",54,12,"kg","Shree Farms","Moodbidri","demo"));}
 @GetMapping public List<Map<String,Object>> all(){return items.stream().map(this::pub).toList();}
 @PostMapping public Map<String,Object> create(@RequestHeader(value="X-VegMap-Token",required=false)String t,@RequestBody Listing x){if(!sec.approved(t))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Seller must be approved before publishing.");if(x.vegetable==null||x.vegetable.isBlank()||x.price<0||x.quantity<=0||x.location==null||x.location.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Check vegetable, price, quantity and location.");Seller s=sec.auth(t);x.id=ids.incrementAndGet();x.seller=s.name;x.ownerPhone=s.phone;if(x.shopName==null||x.shopName.isBlank())x.shopName=s.name;if(x.contactPhone==null||x.contactPhone.isBlank())x.contactPhone=s.phone;if(x.unit==null||x.unit.isBlank())x.unit="kg";items.add(0,x);return pub(x);}
 @DeleteMapping("/{id}") public Map<String,Boolean> delete(@RequestHeader(value="X-VegMap-Token",required=false)String t,@PathVariable long id){Seller s=sec.auth(t);Listing x=items.stream().filter(i->i.id==id).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!s.phone.equals(x.ownerPhone))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Can only delete your own listings.");items.remove(x);return Map.of("deleted",true);}
 Map<String,Object> pub(Listing x){Map<String,Object>m=new LinkedHashMap<>();m.put("id",x.id);m.put("vegetable",x.vegetable);m.put("price",x.price);m.put("quantity",x.quantity);m.put("unit",x.unit);m.put("seller",x.seller);m.put("shopName",x.shopName==null?x.seller:x.shopName);m.put("contactPhone",x.contactPhone==null?x.ownerPhone:x.contactPhone);m.put("location",x.location);return m;}
}